        // 空域变化：当前结论必须 STALE，旧 CLEAR 不能当成当前通过
        service.createZone(zoneReq("nz", -90, -90, -80, -80));
        ReviewResultDto stale1 = service.getCurrentReview("st");
        assertEquals("STALE", stale1.conclusion());
