    @Test
    void reviewIdempotentReplayKeepsImmutableResult() {
        service.createRoute(
                new RouteCreateRequest("ir", pts(0, 10, 100, 10), "req-" + rid("route")));
        String requestId = "fixed-review-1";
        ReviewRequest req = new ReviewRequest("ir", 1, 0L, requestId);
