package com.example.starter.domain;

/** 禁飞区状态：只能创建（ACTIVE）或撤销（REVOKED）。 */
public enum ZoneStatus {
    /** 有效禁飞区，参与航线审核。 */
    ACTIVE,
    /** 已撤销禁飞区，不再参与审核，记录保留不可变。 */
    REVOKED
}
package com.example.starter.domain;

/** 审核结论：命中任一有效禁飞区为 BLOCKED，否则 CLEAR。 */
public enum ReviewConclusion {
    /** 航线与全部有效禁飞区均不相交。 */
    CLEAR,
    /** 航线有点或线段与至少一个有效禁飞区相交（含边界接触）。 */
    BLOCKED
}
package com.example.starter;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * 禁飞区域与航线版本审查服务入口。
 * 默认使用嵌入式 H2（MODE=MySQL）内存库，启动时自动建表并初始化全局空域版本，
 * 不依赖外部 MySQL 或 Docker；数据仅保留在 JVM 生命周期内。
 */
