    @Test
    @DisplayName("合成场景：对向直线第 5.5 秒相遇，端点相隔 100 米仍拒绝；推迟到前一结束后成功")
    void opposingHeadOnRejectedThenDelayedSucceeds() {
        createRoute("ra", 0, 0, 100, 0);
        createRoute("rb", 100, 0, 0, 0);
        // A: [0,11) 从 (0,0) 到 (100,0)
